'use client';
import { numberFormat } from '../../internal/intl';
import * as React from 'react';
import { cn, useMergedRef } from '../../internal/cn';
import { named } from '../../internal/component';
import { useLocale, useSettings } from '../../internal/provider';
import { summaryTookFocus } from '../../internal/summaryFocus';
import { en as words } from './labels';
import { FormErrorsContext } from '../../internal/formErrors';

/** One error in the summary: the field it's about and what's wrong. */
export interface ErrorSummaryItem {
  /** The id of the field (the <input>, <select> or <textarea>, or a group's first control) the error is about. */
  field: string;
  /** What's wrong and how to fix it, as the field's own error says it ("Enter your email address"). */
  message: React.ReactNode;
}

export interface ErrorSummaryProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  /** The errors, in the order of the fields on the page. With none, nothing renders. Inside FormErrors, leave it out to
   *  list the form's messages still showing, each linking to its field. */
  errors?: readonly ErrorSummaryItem[] | undefined;
  /** The heading. Default: "There is a problem", or "There are N problems". */
  title?: React.ReactNode | undefined;
  /** The heading's level, h2 to h6, to fit the page's outline. Default: 2. */
  headingLevel?: 2 | 3 | 4 | 5 | 6 | undefined;
  /** Text under the heading, before the list. */
  description?: React.ReactNode | undefined;
  /** Moves focus to the summary when it appears (a submit that failed), so it's read out and seen first. Default: true. */
  autoFocus?: boolean | undefined;
}

function ErrorSummaryRender({ ref, ...props }: ErrorSummaryProps & React.RefAttributes<HTMLDivElement>) {
  const sds = useSettings(words);
  const locale = useLocale();
  const { errors, title, headingLevel, description, autoFocus, className, ...rest } = props;
  const box = React.useRef<HTMLDivElement | null>(null);
  const heading = React.useId();
  // Inside FormErrors with no errors of its own: the form's messages still showing. It takes focus for a new set of
  // errors (the next submit), not when editing a field takes one away.
  const form = React.useContext(FormErrorsContext);
  const fromForm = errors == null && form != null;
  const list: readonly ErrorSummaryItem[] = errors || (form ? form.list() : []);
  // Focus when the summary appears and whenever its errors change (another failed submit): a field added or gone, or
  // a message that says something new ("Enter your password", then "The email or password is not right") (GR120).
  // Messages can be elements, so what they say is read from the rendered links.
  const said = React.useRef('');
  // every render: compares what the errors say now with what they said, and takes focus only when that changed.
  React.useEffect(() => {
    const n = box.current, links = n && n.querySelector('ul');
    const now = !n ? '' : fromForm && form ? 'v' + form.version : list.map((e) => e.field).join('\n') + '\n' + (links ? links.textContent : '');
    if (now === said.current) return;
    said.current = now;
    if (now && autoFocus !== false && n) { n.focus(); summaryTookFocus(n); }
  });
  const mergedRef = useMergedRef(ref, (n) => { box.current = n; });
  if (!list.length) return null;
  const level = [2, 3, 4, 5, 6].indexOf(headingLevel as number) < 0 ? 2 : (headingLevel as number);
  return (
    <div tabIndex={-1} aria-labelledby={heading} {...rest} ref={mergedRef} className={cn('srp-error-summary', className)} data-component="error-summary">
      {React.createElement('h' + level, { id: heading, className: 'srp-error-summary__title' }, title != null ? title : sds.labels.errorSummaryTitle(list.length, numberFormat(locale).format(list.length)))}
      {description != null ? <div className="srp-error-summary__description">{description}</div> : null}
      <ul className="srp-error-summary__list" role="list">
        {list.map((e, k) => (
          <li key={e.field + k} className="srp-error-summary__item">
            <a className="srp-error-summary__link" href={'#' + e.field} onClick={(ev) => go(ev, e.field)}>{e.message}</a>
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ErrorSummary: after a submit fails, a box at the top of the form with a heading and a list of what's wrong, each
   error a link to its field. It renders only with errors. When it appears, and again when a later submit fails with it
   still showing (its errors change), it takes focus (tabIndex -1, named by its heading), so a screen reader reads it
   and the page scrolls to it. A link moves focus to its field and scrolls the field's label into view, not just the
   control, so the question shows above the answer. className and other props go to the box. */
/** After a failed submit: a heading and a list of the form's errors, each a link that moves focus to its field. */
export const ErrorSummary = /* @__PURE__ */ named('ErrorSummary', ErrorSummaryRender);

// A link moves focus to its field and shows the field's label at the top, not the bare control: for a radio or checkbox
// in a fieldset, the group's legend (the question), else its own label.
// One whose field isn't on the page follows its href like any link.
function go(ev: React.MouseEvent<HTMLAnchorElement>, field: string) {
  const doc = ev.currentTarget.ownerDocument, to = doc.getElementById(field);
  if (!to || ev.defaultPrevented || ev.button !== 0 || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) return;
  ev.preventDefault();
  // A field in a closed AccordionItem or on another tab is hidden="until-found": as the browser does on reaching one
  // (find-in-page, a #link), fire beforematch, which opens the item or selects the tab, and show it; then focus it
  // once that has rendered. The link did nothing, as nothing hidden takes focus (L8E98).
  let hid = 0;
  for (let h; (h = to.closest('[hidden=until-found]')); hid = 1) { h.dispatchEvent(new Event('beforematch')); h.removeAttribute('hidden'); }
  if (hid) setTimeout(() => land(to)); else land(to);
}
function land(to: HTMLElement) {
  // The control that takes focus decides: a link to a RadioGroup's root lands on a radio, and shows its legend too (L8E56).
  const target = inner(to), input = target as HTMLInputElement, set = target.closest('fieldset');
  const legend = set && (input.type === 'radio' || input.type === 'checkbox') ? set.querySelector('legend') : null;
  // A group outside a fieldset shows itself, not the one radio's label.
  const shown = legend || (target === to && input.labels && input.labels[0]) || to;
  // jsdom (where apps run unit tests) has no scrollIntoView: the link still moves focus there (L8E46).
  if (typeof shown.scrollIntoView === 'function') shown.scrollIntoView({ block: 'start' });
  target.focus({ preventScroll: true });
}

// A field id on a group that can't take focus itself (RadioGroup's or Rating's root): its checked radio, else the
// first enabled control in it, as Tab would reach the group (GR15).
const FOCUSABLE = "input:not(:disabled):not([type=hidden]), select:not(:disabled), textarea:not(:disabled), button:not(:disabled), a[href], [tabindex]:not([tabindex='-1'])";
function inner(to: HTMLElement): HTMLElement {
  if (to.matches(FOCUSABLE) || to.isContentEditable) return to;
  return to.querySelector<HTMLElement>('input:checked:not(:disabled), [aria-checked=true]:not([aria-disabled=true])') || to.querySelector<HTMLElement>(FOCUSABLE) || to;
}
